import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import API from '../api';

const BUSINESS_TYPES = [
  // Startups & Entrepreneurs
  'Tech startups (apps, software, IT services)',
  'E-commerce businesses',
  'Digital service startups',
  'Creative startups (design, media, photography)',
  // Retail & Wholesale
  'Shops and minimarkets',
  'Clothing and fashion stores',
  'Shoe and accessories shops',
  'Electronics and mobile phone shops',
  'Cosmetics and beauty product shops',
  'Bookshops and stationery shops',
  'Furniture and home appliance shops',
  'Food and beverage wholesalers',
  'Construction material suppliers',
  'Agricultural input suppliers',
  'Textile and garment wholesalers',
  // Hospitality & Tourism
  'Restaurants and cafes',
  'Traditional food houses',
  'Event and conference venues',
  'Car rental services',
  // Educational Institutions
  'Private schools (KG–Grade 12)',
  'Training centers',
  'Language schools',
  'Computer and IT training centers',
  'Tutorial and exam preparation centers',
  'Online learning platforms',
  'Educational consultancy services',
  // Service Providers
  'Advertising and marketing agencies',
  'Printing and publishing services',
  'Graphic design and branding services',
  'Accounting and auditing firms',
  'Legal and consultancy services',
  'Cleaning and maintenance services',
  'Security service providers',
  'Beauty salons and barber shops',
  'Transportation and logistics services',
  // Manufacturers
  'Food and beverage processing enterprises',
  'Garment and textile manufacturers',
  'Shoe and leather product manufacturers',
  'Plastic product manufacturers',
  'Metal and wood furniture manufacturers',
  'Building material manufacturers',
  'Packaging and labeling manufacturers',
  'Other',
];

const STEPS = ['Account', 'Business Info', 'Documents'];

export default function Register() {
  const navigate = useNavigate();
  const [step, setStep] = useState(0);
  const [form, setForm] = useState({
    full_name: '', email: '', password: '', confirm_password: '',
    phone: '', company_name: '', business_type: '',
    tin_number: '', elmis_registration: '', business_license_number: '',
    location: '', website: '',
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const set = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const nextStep = () => {
    setError('');
    if (step === 0) {
      if (!form.full_name || !form.phone || !form.password) return setError('Please fill all required fields.');
      if (form.password !== form.confirm_password) return setError('Passwords do not match.');
      if (form.password.length < 6) return setError('Password must be at least 6 characters.');
    }
    if (step === 1) {
      if (!form.company_name) return setError('Company name is required.');
    }
    setStep((s) => s + 1);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.business_license_number) return setError('Business license number is required.');
    setLoading(true);
    setError('');
    try {
      const { data } = await API.post('/users/register', form);
      localStorage.setItem('userToken', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px 24px', background: '#0a0a0a' }}>
      <div style={{ width: '100%', maxWidth: 520 }}>
        <div style={{ textAlign: 'center', marginBottom: 32 }}>
          <h1 style={{ fontSize: 28, fontWeight: 900 }}>All <span style={{ color: '#f97316' }}>Things</span></h1>
          <p style={{ color: '#a3a3a3', marginTop: 6 }}>Create your business account</p>
        </div>

        {/* Step indicator */}
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: 32 }}>
          {STEPS.map((label, i) => (
            <React.Fragment key={label}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', flex: 1 }}>
                <div style={{ width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, fontWeight: 700,
                  background: i < step ? '#22c55e' : i === step ? '#f97316' : '#262626',
                  color: i <= step ? '#000' : '#666' }}>
                  {i < step ? '✓' : i + 1}
                </div>
                <span style={{ fontSize: 11, color: i === step ? '#f97316' : '#666', marginTop: 4 }}>{label}</span>
              </div>
              {i < STEPS.length - 1 && (
                <div style={{ flex: 1, height: 2, background: i < step ? '#22c55e' : '#262626', margin: '0 4px', marginBottom: 20 }} />
              )}
            </React.Fragment>
          ))}
        </div>

        <div style={{ background: '#171717', border: '1px solid #262626', borderRadius: 16, padding: 32 }}>
          {error && <div style={errStyle}>{error}</div>}

          {step === 0 && (
            <div>
              <h3 style={{ fontSize: 16, color: '#f97316', marginBottom: 20 }}>Account Details</h3>
              <Field label="Full Name *" name="full_name" value={form.full_name} onChange={set} />
              <Field label="Phone Number *" name="phone" value={form.phone} onChange={set} placeholder="+251 9XX XXX XXX" />
              <Field label="Email Address (optional)" name="email" type="email" value={form.email} onChange={set} />
              <Field label="Password *" name="password" type="password" value={form.password} onChange={set} placeholder="Min. 6 characters" />
              <Field label="Confirm Password *" name="confirm_password" type="password" value={form.confirm_password} onChange={set} />
              <button onClick={nextStep} style={btnPrimary}>Next: Business Info →</button>
            </div>
          )}

          {step === 1 && (
            <div>
              <h3 style={{ fontSize: 16, color: '#f97316', marginBottom: 20 }}>Business Information</h3>
              <Field label="Company / Business Name *" name="company_name" value={form.company_name} onChange={set} />
              <div style={{ marginBottom: 16 }}>
                <label style={labelStyle}>Business Type</label>
                <select name="business_type" value={form.business_type} onChange={set} style={inputStyle}>
                  <option value="">Select type...</option>
                  {BUSINESS_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <Field label="Location" name="location" value={form.location} onChange={set} placeholder="City, Ethiopia" />
              <Field label="Website (optional)" name="website" value={form.website} onChange={set} placeholder="www.yourbusiness.com" />
              <div style={{ display: 'flex', gap: 10 }}>
                <button onClick={() => setStep(0)} style={btnSecondary}>← Back</button>
                <button onClick={nextStep} style={{ ...btnPrimary, flex: 1 }}>Next: Documents →</button>
              </div>
            </div>
          )}

          {step === 2 && (
            <form onSubmit={handleSubmit}>
              <h3 style={{ fontSize: 16, color: '#f97316', marginBottom: 8 }}>Business Documents</h3>
              <p style={{ color: '#a3a3a3', fontSize: 13, marginBottom: 20 }}>We only work with licensed businesses. Please provide your official document numbers.</p>
              <Field label="Business License Number *" name="business_license_number" value={form.business_license_number} onChange={set} />
              <Field label="TIN Number" name="tin_number" value={form.tin_number} onChange={set} />
              <Field label="E-LMIS Registration" name="elmis_registration" value={form.elmis_registration} onChange={set} />
              <div style={{ background: '#f9731610', border: '1px solid #f9731630', borderRadius: 10, padding: 14, marginBottom: 20, fontSize: 13, color: '#a3a3a3' }}>
                📋 Your information will be reviewed by our team. You'll receive a welcome email after registration.
              </div>
              <div style={{ display: 'flex', gap: 10 }}>
                <button type="button" onClick={() => setStep(1)} style={btnSecondary}>← Back</button>
                <button type="submit" disabled={loading} style={{ ...btnPrimary, flex: 1 }}>
                  {loading ? 'Creating Account...' : 'Create Account →'}
                </button>
              </div>
            </form>
          )}
        </div>

        <p style={{ textAlign: 'center', color: '#a3a3a3', marginTop: 20, fontSize: 14 }}>
          Already have an account? <Link to="/login" style={{ color: '#f97316' }}>Sign in</Link>
        </p>
      </div>
    </div>
  );
}

const Field = ({ label, name, type = 'text', value, onChange, placeholder }) => (
  <div style={{ marginBottom: 16 }}>
    <label style={labelStyle}>{label}</label>
    <input type={type} name={name} value={value} onChange={onChange} placeholder={placeholder} style={inputStyle} />
  </div>
);

const inputStyle = { width: '100%', padding: '11px 14px', background: '#0a0a0a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: 14 };
const labelStyle = { display: 'block', fontSize: 13, color: '#a3a3a3', marginBottom: 6 };
const btnPrimary = { width: '100%', padding: '13px', background: '#f97316', color: '#000', border: 'none', borderRadius: 8, fontWeight: 700, fontSize: 15, cursor: 'pointer' };
const btnSecondary = { padding: '13px 20px', background: '#262626', color: '#fff', border: '1px solid #333', borderRadius: 8, fontWeight: 600, fontSize: 14, cursor: 'pointer' };
const errStyle = { background: '#ef444420', border: '1px solid #ef4444', color: '#ef4444', padding: '10px 14px', borderRadius: 8, marginBottom: 16, fontSize: 14 };
